class Solution {
    fun minChanges(nums:IntArray,k:Int):Int{
        val inf=1_000_000;
        var dp=IntArray(1024){
            inf
        };
        dp[0]=0;
        for(group in 0 until k){
            val count=IntArray(1024);
            var size=0;
            for(i in group until nums.size step k){
                count[nums[i]]++;
                size++
            };
            val minimum=dp.minOrNull()!!;
            val next=IntArray(1024){
                minimum+size
            };
            for(state in 0 until 1024)for(value in 0 until 1024)if(count[value]>0)next[state xor value]=minOf(next[state xor value],dp[state]+size-count[value]);
            dp=next
        };
        return dp[0]
    }
}

